<script setup lang="ts">
import {apiError} from './apiError';
import {ref,watch} from 'vue';
const props=defineProps<{result:any}>();
const parameters=ref<Record<string,number>>({});const wind=ref(1);const pv=ref(1);const busy=ref(false);const error=ref('');const comparison=ref<any>(null);
const labels:Record<string,string>={storage_power_kw:'储能总功率 / kW',storage_energy_kwh:'储能总容量 / kWh',emergency_gen_kw:'应急电源总功率 / kW',grid_channel_kw:'外部供电总上限 / kW',soc_initial_ratio:'初始SOC / 比例'};
const metrics:Record<string,string>={max_power_deficit_kw:'最大功率缺额 / kW',expected_energy_deficit_kwh:'缺供电量 / kWh',critical_load_supply_ratio:'关键负荷电量满足率 / 比例'};
watch(()=>props.result?.id,()=>{parameters.value={...props.result?.parameters};comparison.value=null;wind.value=1;pv.value=1},{immediate:true});
watch([parameters,wind,pv],()=>{comparison.value=null},{deep:true});
async function calculate(){busy.value=true;error.value='';comparison.value=null;try{const response=await fetch('/api/strategy-evaluation',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({source_run_id:props.result.id,parameters:parameters.value,wind_scale:wind.value,pv_scale:pv.value})});const data=await response.json();if(!response.ok)throw Error(apiError(data.detail));comparison.value=data}catch(e){error.value=String(e)}finally{busy.value=false}}
</script>
<template><p v-if="!result" id="strategy-adjustment" class="notice">请先计算或加载基准结果，再调整资源。</p><p v-if="!comparison" id="strategy-comparison" class="notice">尚无本次效果对比，请先完成资源调整复算。</p><article id="strategy-library"><h3>策略触发建议</h3><p>采用课题2研究代码默认阈值，规则触发仅供选择改进方向。</p><p v-if="result?.metric_definitions">孤岛支撑需求 {{result.metrics.island_required_hours}} h；嵌入事件 {{result.metrics.extreme_event_hours}} h。{{result.metric_definitions.island_required_hours}}</p><p v-if="!result">请先完成平衡计算或加载历史结果。</p><div v-for="s in result?.strategies" class="strategy"><b>{{s.triggered?'● 已触发':'○ 未触发'}} · {{s.strategy}}</b><p>{{s.reason}}</p><small>{{s.config_hint}}</small></div></article><article id="strategy-adjustment" v-if="result"><h3>资源调整与效果复算</h3><p>基准 {{result.id.slice(0,8)}}。以下资源为调整后的总量；复算沿用基准的阶段、故障和接入位置。风光系数作用于出力曲线，未模拟移动资源行程或新增设备选址。</p><div class="grid"><div><label v-for="(label,key) in labels" class="field">{{label}}<input type="number" min="0" step="any" v-model.number="parameters[key]" :disabled="busy"></label></div><div><label class="field">风电出力系数<input type="number" min="0" max="10" step=".1" v-model.number="wind" :disabled="busy"></label><label class="field">光伏出力系数<input type="number" min="0" max="10" step=".1" v-model.number="pv" :disabled="busy"></label><button class="primary" @click="calculate" :disabled="busy">{{busy?'正在复算…':'按调整资源复算并归档'}}</button></div></div><p v-if="error" class="error">{{error}}</p><template v-if="comparison"><p id="strategy-comparison">{{comparison.interpretation}}</p><table><tr><th>指标</th><th>基准</th><th>调整后</th></tr><tr v-for="(label,key) in metrics"><td>{{label}}</td><td>{{comparison.baseline[key].toFixed(3)}}</td><td>{{comparison.verified[key].toFixed(3)}}</td></tr></table><a :href="'/api/runs/'+comparison.run_id+'/report'">导出调整方案计算报告</a></template></article></template>
